const input = $input.first() ? $input.first().json : {};
const body = input.body || input;
// If rootFolderId is omitted or "ALL", scans the ENTIRE My Drive across all folders!
const rootFolderId = body.rootFolderId || 'ALL';
const dryRun = body.dryRun === true;
const targetOwnerEmail = (body.ownerEmail || 'user@example.com').toLowerCase().trim();

const ownedFoldersQ = encodeURIComponent("mimeType = 'application/vnd.google-apps.folder' and 'me' in owners and trashed = false");
const ownedFoldersFields = encodeURIComponent("files(id,name,parents)");
const listOwnedFoldersUrl = `https://www.googleapis.com/drive/v3/files?q=${ownedFoldersQ}&fields=${ownedFoldersFields}&pageSize=1000`;

const unownedQ = encodeURIComponent("not 'me' in owners and trashed = false");
const unownedFields = encodeURIComponent("files(id,name,mimeType,owners(emailAddress,me),parents,webViewLink,shortcutDetails)");
const listUnownedUrl = `https://www.googleapis.com/drive/v3/files?q=${unownedQ}&fields=${unownedFields}&pageSize=1000`;

return [{
  json: {
    rootFolderId,
    dryRun,
    targetOwnerEmail,
    listOwnedFoldersUrl,
    listUnownedUrl
  }
}];

const cfg = $('1. Config (Entire Drive or Folder)').first().json;
const driveRoot = $('2. HTTP: Get My Drive Root ID').first().json;
const myDriveRootId = driveRoot.id;
const ownedFolders = ($('3. HTTP: List All Owned Folders in Drive').first().json.files || []);
const allUnowned = ($input.first().json.files || []);

// Build set of owned folder IDs in scope
const ownedFolderMap = {};
ownedFolderMap[myDriveRootId] = { id: myDriveRootId, name: 'My Drive', parents: [] };
for (const f of ownedFolders) {
  ownedFolderMap[f.id] = f;
}

// If a specific rootFolderId was requested, restrict ownedFoldersInScope to that folder and its descendants
const inScopeOwnedFolderIds = new Set();
if (!cfg.rootFolderId || cfg.rootFolderId === 'ALL') {
  inScopeOwnedFolderIds.add(myDriveRootId);
  for (const f of ownedFolders) {
    inScopeOwnedFolderIds.add(f.id);
  }
} else {
  inScopeOwnedFolderIds.add(cfg.rootFolderId);
  let added = true;
  while (added) {
    added = false;
    for (const f of ownedFolders) {
      if (!inScopeOwnedFolderIds.has(f.id) && (f.parents || []).some(p => inScopeOwnedFolderIds.has(p))) {
        inScopeOwnedFolderIds.add(f.id);
        added = true;
      }
    }
  }
}

// Map all unowned folders and files that reside inside inScopeOwnedFolderIds (at any depth!)
const unownedById = {};
for (const item of allUnowned) {
  unownedById[item.id] = item;
}

// Determine which unowned items have an ancestor in inScopeOwnedFolderIds
const inScopeUnownedIds = new Set();
let changed = true;
while (changed) {
  changed = false;
  for (const item of allUnowned) {
    if (inScopeUnownedIds.has(item.id)) continue;
    const p = (item.parents && item.parents[0]) || '';
    if (p && (inScopeOwnedFolderIds.has(p) || inScopeUnownedIds.has(p))) {
      inScopeUnownedIds.add(item.id);
      changed = true;
    }
  }
}

const inScopeUnowned = allUnowned.filter(item => inScopeUnownedIds.has(item.id));
const unownedFolders = inScopeUnowned.filter(item => item.mimeType === 'application/vnd.google-apps.folder');
const unownedFiles = inScopeUnowned.filter(item => item.mimeType !== 'application/vnd.google-apps.folder' && item.mimeType !== 'application/vnd.google-apps.shortcut');

// Check if an owned folder with the same name & parent already exists
const ownedFoldersByParentAndName = {};
for (const f of ownedFolders) {
  const p = (f.parents && f.parents[0]) || myDriveRootId;
  ownedFoldersByParentAndName[`${p}::${f.name}`] = f;
}

const unownedFoldersToCreate = [];
const preExistingFolderMap = {};

// Topologically sort unownedFolders from parent to child
const sortedUnownedFolders = [];
const visitedFolders = new Set();
let progress = true;
while (progress && sortedUnownedFolders.length < unownedFolders.length) {
  progress = false;
  for (const f of unownedFolders) {
    if (visitedFolders.has(f.id)) continue;
    const p = (f.parents && f.parents[0]) || '';
    if (inScopeOwnedFolderIds.has(p) || visitedFolders.has(p)) {
      sortedUnownedFolders.push(f);
      visitedFolders.add(f.id);
      progress = true;
    }
  }
}
for (const f of unownedFolders) {
  if (!visitedFolders.has(f.id)) sortedUnownedFolders.push(f);
}

for (const f of sortedUnownedFolders) {
  const origParent = (f.parents && f.parents[0]) || myDriveRootId;
  const existing = ownedFoldersByParentAndName[`${origParent}::${f.name}`];
  if (existing) {
    preExistingFolderMap[f.id] = existing.id;
  } else {
    unownedFoldersToCreate.push({
      oldFolderId: f.id,
      name: f.name,
      origParent
    });
  }
}

if (cfg.dryRun || unownedFoldersToCreate.length === 0) {
  return [{
    json: {
      hasFoldersToCreate: false,
      dryRun: cfg.dryRun,
      myDriveRootId,
      oldFolderId: '',
      name: '',
      origParent: myDriveRootId,
      preExistingFolderMap,
      unownedFolders,
      unownedFiles,
      inScopeOwnedFolderIds: Array.from(inScopeOwnedFolderIds)
    }
  }];
}

// Note: for nested unowned folders where parent is also an unowned folder, parentId is resolved if top-level or falls back to origParent
return unownedFoldersToCreate.map(f => ({
  json: {
    hasFoldersToCreate: true,
    dryRun: cfg.dryRun,
    myDriveRootId,
    oldFolderId: f.oldFolderId,
    name: f.name,
    origParent: preExistingFolderMap[f.origParent] || f.origParent,
    preExistingFolderMap,
    unownedFolders,
    unownedFiles,
    inScopeOwnedFolderIds: Array.from(inScopeOwnedFolderIds)
  }
}));

const plannedItems = $('5. Code: Find Foreign Items Across Drive & Plan Subfolders').all().map(i => i.json);
const firstPlan = plannedItems[0] || {};
const unownedFolders = firstPlan.unownedFolders || [];
const unownedFiles = firstPlan.unownedFiles || [];
const folderIdMap = { ...(firstPlan.preExistingFolderMap || {}) };
const createdFolders = [];

if (firstPlan.hasFoldersToCreate) {
  const httpResponses = $input.all().map(i => i.json);
  for (let idx = 0; idx < plannedItems.length; idx++) {
    const oldId = plannedItems[idx].oldFolderId;
    const created = httpResponses[idx] || {};
    if (oldId && created.id) {
      folderIdMap[oldId] = created.id;
      createdFolders.push({
        oldId,
        newId: created.id,
        name: created.name,
        webViewLink: created.webViewLink
      });
    }
  }
}

const filesToCopy = unownedFiles.map(f => {
  const origParent = (f.parents && f.parents[0]) || firstPlan.myDriveRootId;
  const targetParent = folderIdMap[origParent] || origParent;
  return {
    oldFileId: f.id,
    name: f.name,
    mimeType: f.mimeType,
    origParent,
    targetParent,
    owners: (f.owners || []).map(o => o.emailAddress)
  };
});

if (firstPlan.dryRun || filesToCopy.length === 0) {
  return [{
    json: {
      hasFilesToCopy: false,
      dryRun: firstPlan.dryRun,
      myDriveRootId: firstPlan.myDriveRootId,
      oldFileId: '',
      name: '',
      mimeType: '',
      origParent: '',
      targetParent: firstPlan.myDriveRootId,
      folderIdMap,
      createdFolders,
      unownedFolders,
      unownedFiles,
      plannedFileCopies: filesToCopy
    }
  }];
}

return filesToCopy.map(f => ({
  json: {
    hasFilesToCopy: true,
    dryRun: firstPlan.dryRun,
    myDriveRootId: firstPlan.myDriveRootId,
    ...f,
    folderIdMap,
    createdFolders,
    unownedFolders,
    unownedFiles,
    plannedFileCopies: filesToCopy
  }
}));

const firstFolderPlan = $('5. Code: Find Foreign Items Across Drive & Plan Subfolders').first().json;
const plannedFiles = $('8. Code: Plan File Copies Across Drive').all().map(i => i.json);
const firstPlan = plannedFiles[0] || {};
const folderIdMap = firstPlan.folderIdMap || {};
const createdFolders = firstPlan.createdFolders || [];
const fileIdMap = {};
const copiedFiles = [];

if (firstPlan.hasFilesToCopy) {
  const httpResponses = $input.all().map(i => i.json);
  for (let idx = 0; idx < plannedFiles.length; idx++) {
    const plan = plannedFiles[idx];
    const copied = httpResponses[idx] || {};
    if (plan.oldFileId && copied.id) {
      fileIdMap[plan.oldFileId] = copied.id;
      copiedFiles.push({
        oldId: plan.oldFileId,
        newId: copied.id,
        name: copied.name || plan.name,
        mimeType: copied.mimeType || plan.mimeType,
        targetParent: plan.targetParent,
        webViewLink: copied.webViewLink
      });
    }
  }
}

// Remove any foreign-owned item whose parent is an owned folder in scope (so it is cleanly unlinked from My Drive)
const ownedScopeSet = new Set(firstFolderPlan.inScopeOwnedFolderIds || []);
const allInScopeUnowned = [...(firstPlan.unownedFolders || []), ...(firstPlan.unownedFiles || [])];
const topLevelForeignItems = allInScopeUnowned.filter(item => {
  const p = (item.parents && item.parents[0]) || '';
  return ownedScopeSet.has(p);
});

if (firstPlan.dryRun || topLevelForeignItems.length === 0) {
  return [{
    json: {
      hasRemovals: false,
      dryRun: firstPlan.dryRun,
      itemId: '',
      name: '',
      parentToRemove: '',
      folderIdMap,
      fileIdMap,
      createdFolders,
      copiedFiles,
      plannedFileCopies: firstPlan.plannedFileCopies || [],
      unownedFolders: firstPlan.unownedFolders || []
    }
  }];
}

return topLevelForeignItems.map(f => ({
  json: {
    hasRemovals: true,
    dryRun: firstPlan.dryRun,
    itemId: f.id,
    name: f.name,
    mimeType: f.mimeType,
    parentToRemove: f.parents[0],
    folderIdMap,
    fileIdMap,
    createdFolders,
    copiedFiles,
    plannedFileCopies: firstPlan.plannedFileCopies || [],
    unownedFolders: firstPlan.unownedFolders || []
  }
}));

const cfg = $('1. Config (Entire Drive or Folder)').first().json;
const cleanupPlans = $('11. Code: Plan Foreign Original Cleanup').all().map(i => i.json);
const firstPlan = cleanupPlans[0] || {};

const removedOriginals = [];
if (firstPlan.hasRemovals) {
  const responses = $input.all().map(i => i.json);
  for (let idx = 0; idx < cleanupPlans.length; idx++) {
    removedOriginals.push({
      id: cleanupPlans[idx].itemId,
      name: cleanupPlans[idx].name,
      mimeType: cleanupPlans[idx].mimeType,
      removedFromParent: cleanupPlans[idx].parentToRemove,
      status: 'removed_from_folder'
    });
  }
}

return [{
  json: {
    status: 'success',
    scope: cfg.rootFolderId === 'ALL' ? 'ENTIRE_MY_DRIVE' : cfg.rootFolderId,
    dryRun: cfg.dryRun,
    targetOwnerEmail: cfg.targetOwnerEmail,
    summary: {
      detectedForeignFoldersInDrive: (firstPlan.unownedFolders || []).length,
      detectedForeignFilesInDrive: (firstPlan.plannedFileCopies || []).length,
      createdFoldersCount: (firstPlan.createdFolders || []).length,
      copiedFilesCount: (firstPlan.copiedFiles || []).length,
      removedOriginalsCount: removedOriginals.length
    },
    detectedForeignFolders: (firstPlan.unownedFolders || []).map(f => ({
      id: f.id,
      name: f.name,
      parents: f.parents,
      owners: (f.owners || []).map(o => o.emailAddress)
    })),
    detectedForeignFiles: firstPlan.plannedFileCopies || [],
    createdFolders: firstPlan.createdFolders || [],
    copiedFiles: firstPlan.copiedFiles || [],
    folderIdMap: firstPlan.folderIdMap || {},
    fileIdMap: firstPlan.fileIdMap || {},
    removedOriginals
  }
}];
